import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.DNmTgtHf.js";const k=JSON.parse('{"title":"HashMap Internals","description":"","frontmatter":{},"headers":[],"relativePath":"java/foundations/hashmap/HashMap.md","filePath":"java/foundations/hashmap/HashMap.md"}'),n={name:"java/foundations/hashmap/HashMap.md"};function h(l,e,o,r,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="hashmap-internals" tabindex="-1">HashMap Internals <a class="header-anchor" href="#hashmap-internals" aria-label="Permalink to &quot;HashMap Internals&quot;">​</a></h1><hr><h2 id="internal-structure" tabindex="-1">Internal structure <a class="header-anchor" href="#internal-structure" aria-label="Permalink to &quot;Internal structure&quot;">​</a></h2><p>A <code>HashMap&lt;K,V&gt;</code> is backed by a single array of buckets:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Node&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">K</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">V</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;[] table;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// length is always a power of 2</span></span></code></pre></div><p>Each slot in <code>table</code> is either <code>null</code> (empty bucket) or the head of a chain. A <code>Node</code> holds four fields:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Node&lt;K,V&gt;</span></span>
<span class="line"><span>  int    hash   — cached hash of the key (avoids recomputing on resize)</span></span>
<span class="line"><span>  K      key</span></span>
<span class="line"><span>  V      value</span></span>
<span class="line"><span>  Node   next   — pointer to the next node in the same bucket (linked list)</span></span></code></pre></div><p>When a bucket&#39;s chain grows long enough (see Collision handling), Java 8 replaces the linked list with a Red-Black tree using <code>TreeNode&lt;K,V&gt;</code>, which extends <code>Node</code>.</p><p><strong>Key defaults:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default value</th></tr></thead><tbody><tr><td>Initial capacity</td><td>16</td></tr><tr><td>Load factor</td><td>0.75</td></tr><tr><td>Treeify threshold</td><td>8 (chain length at which list becomes tree)</td></tr><tr><td>Untreeify threshold</td><td>6 (chain length at which tree reverts to list)</td></tr></tbody></table><hr><h2 id="hash-calculation" tabindex="-1">Hash calculation <a class="header-anchor" href="#hash-calculation" aria-label="Permalink to &quot;Hash calculation&quot;">​</a></h2><p>When you call <code>map.put(key, value)</code>, the map first computes a spread hash:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Object key) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> h;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (h </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> key.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hashCode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (h </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Then it finds the bucket index:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hash   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// n = table.length</span></span></code></pre></div><p><strong>Why XOR with the upper 16 bits:</strong> <code>hashCode()</code> often has entropy concentrated in the higher bits. When the table is small (e.g., capacity 16), only the lowest 4 bits of the hash determine the bucket — the upper bits are ignored. XOR-ing the upper half down into the lower half folds that entropy in, reducing clustering even with poor <code>hashCode()</code> implementations.</p><p><strong>Why <code>(n - 1) &amp; hash</code> instead of <code>hash % n</code>:</strong> when <code>n</code> is a power of 2, <code>n - 1</code> is all 1-bits, so the AND is a cheap bitwise mask that extracts exactly the low <code>log2(n)</code> bits. This is why capacity must always be a power of 2 — otherwise <code>(n - 1)</code> wouldn&#39;t be a mask and the trick wouldn&#39;t work.</p><hr><h2 id="collision-handling" tabindex="-1">Collision handling <a class="header-anchor" href="#collision-handling" aria-label="Permalink to &quot;Collision handling&quot;">​</a></h2><p>A collision is when two distinct keys map to the same bucket index. Both nodes end up in that bucket&#39;s chain.</p><p><strong>Java 7 and earlier:</strong> all buckets are linked lists. With a poor hash function or many collisions, a chain can grow to O(n), making worst-case get/put O(n).</p><p><strong>Java 8+ (JEP 180):</strong> automatic treeification.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bucket chain length:</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 1  2  3  4  5  6  7   8 → treeify (only if table.length &gt;= 64)</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span>                   Red-Black tree (O(log n) ops)</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span> 6 → untreeify back to linked list</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Phase</th><th>Structure</th><th>get/put complexity</th></tr></thead><tbody><tr><td>Chain length &lt; 8</td><td>Linked list</td><td>O(n) worst case</td></tr><tr><td>Chain length &gt;= 8 AND table.length &gt;= 64</td><td>Red-Black tree</td><td>O(log n) worst case</td></tr><tr><td>Chain length &gt;= 8 AND table.length &lt; 64</td><td>Resize instead of treeify</td><td>—</td></tr><tr><td>Tree shrinks to &lt;= 6</td><td>Reverts to linked list</td><td>O(n) worst case</td></tr></tbody></table><p><strong>Why treeify at 8 and untreeify at 6 (not both at 8):</strong> the gap creates hysteresis. If both thresholds were 8, a bucket hovering at exactly 8 entries would thrash — each put/remove would trigger a treeify/untreeify. The two-unit gap prevents that oscillation.</p><p><strong>The table-size guard (<code>MIN_TREEIFY_CAPACITY = 64</code>):</strong> treeifying a tiny table is counterproductive — a small table with a long chain usually means a bad hash function affecting all buckets, so resizing (spreading entries across more buckets) fixes the real problem. Treeification is deferred until the table is large enough that a single pathological chain is the exception.</p><hr><h2 id="resize-and-rehash" tabindex="-1">Resize and rehash <a class="header-anchor" href="#resize-and-rehash" aria-label="Permalink to &quot;Resize and rehash&quot;">​</a></h2><p>Resize triggers when the total entry count crosses the threshold:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>threshold = capacity × loadFactor</span></span>
<span class="line"><span>           = 16 × 0.75 = 12   (with defaults)</span></span></code></pre></div><p>When <code>size &gt; threshold</code>:</p><ol><li>A new <code>table</code> is allocated at <code>2 × oldCapacity</code>.</li><li>Every existing entry is rehashed and placed in the new table — O(n) work.</li><li>The threshold is recalculated: <code>newCapacity × loadFactor</code>.</li></ol><p>Because the new capacity is exactly double the old (still a power of 2), Java 8 uses a trick: an entry either stays at the same index or moves to <code>oldIndex + oldCapacity</code>. The decision is one bit of the cached hash — no full re-hash needed. This makes Java 8 resize faster than Java 7&#39;s full rehash.</p><p><strong>Why load factor 0.75:</strong></p><ul><li>Too low (e.g., 0.5): resize early, many empty buckets, wastes memory.</li><li>Too high (e.g., 1.0): resize late, long chains, more collisions, slower lookups.</li><li>0.75 is the empirical sweet spot between time (collision rate) and space (wasted capacity), noted explicitly in the Java source.</li></ul><hr><h2 id="null-key" tabindex="-1">Null key <a class="header-anchor" href="#null-key" aria-label="Permalink to &quot;Null key&quot;">​</a></h2><p><code>null</code> is a valid key. <code>hash(null)</code> returns 0, so a null key always lands in <code>table[0]</code>. Only one null key can exist — subsequent puts replace the value, as with any key.</p><hr><h2 id="complexity-summary" tabindex="-1">Complexity summary <a class="header-anchor" href="#complexity-summary" aria-label="Permalink to &quot;Complexity summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Average case</th><th>Worst case</th></tr></thead><tbody><tr><td><code>put</code> / <code>get</code> / <code>remove</code></td><td>O(1) amortized</td><td>O(log n) — tree bin after treeification</td></tr><tr><td>Resize (rare)</td><td>O(n)</td><td>O(n)</td></tr></tbody></table><p>&quot;Amortized O(1)&quot; means most operations touch one bucket; resize spreads its cost across all preceding puts. The tree bin worst case of O(log n) applies only to degenerate keys (e.g., many keys with the same <code>hashCode()</code>).</p><hr><h2 id="not-thread-safe" tabindex="-1">Not thread-safe <a class="header-anchor" href="#not-thread-safe" aria-label="Permalink to &quot;Not thread-safe&quot;">​</a></h2><p><code>HashMap</code> has no internal synchronization. Concurrent modification can corrupt the map:</p><ul><li><strong>Lost updates:</strong> two threads writing to the same bucket simultaneously can silently drop one entry.</li><li><strong>Infinite loop during resize (Java 7):</strong> the Java 7 resize algorithm could form a cycle in a bucket&#39;s linked list under concurrent rehash. Reads then spin forever. Java 8 fixed the cycle but the map is still unsynchronized and unsafe to share.</li><li><strong>Visibility:</strong> without synchronization, one thread may not see writes made by another.</li></ul><p>For concurrent access use <code>ConcurrentHashMap</code> — segmented locks (Java 7) or CAS + synchronized on individual bins (Java 8+).</p><hr><h2 id="mutable-keys" tabindex="-1">Mutable keys <a class="header-anchor" href="#mutable-keys" aria-label="Permalink to &quot;Mutable keys&quot;">​</a></h2><p><code>HashMap</code> caches the spread hash in each <code>Node</code> at insert time (the <code>int hash</code> field). That cached value is never updated. If you mutate a key after insertion, <code>hashCode()</code> returns a different value — the map looks in the wrong bucket on the next <code>get</code>, finds nothing, returns <code>null</code>. The entry is still in the original bucket, permanently orphaned.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Person p </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Person</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Alice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">map.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(p, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;engineer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// hashCode() → bucket 5, cached there</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bob&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// mutation — hashCode() now produces a different int</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">map.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(p);              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// looks in new bucket → null</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         // entry still in bucket 5 — lost, no exception</span></span></code></pre></div><p>No exception is thrown. The entry isn&#39;t removed — just unreachable. The map also leaks memory until the next resize.</p><p><strong>Rule:</strong> only use immutable objects as keys (<code>String</code>, <code>Integer</code>, your own <code>record</code> or <code>@Value</code> DTO). If you must use a mutable object, hash only on fields that never change after construction (e.g., a database <code>id</code>).</p><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Why must HashMap capacity always be a power of 2?</strong> A. So that <code>(n - 1) &amp; hash</code> is a cheap bitwise mask equivalent to <code>hash % n</code> — works only when <code>n</code> is a power of 2.</p><p><strong>Q. What does <code>(h = key.hashCode()) ^ (h &gt;&gt;&gt; 16)</code> achieve?</strong> A. Folds the upper 16 bits of the hash into the lower 16, spreading entropy into the bits that actually determine the bucket index when the table is small.</p><p><strong>Q. What is the treeify threshold, and why is the untreeify threshold lower?</strong> A. Treeify at chain length 8 (O(log n) tree instead of O(n) list). Untreeify at 6, not 8 — the two-unit gap prevents thrashing when entries hover right at the boundary.</p><p><strong>Q. Does a chain of 8 always trigger treeification?</strong> A. No. Treeification is skipped when <code>table.length &lt; 64</code> (<code>MIN_TREEIFY_CAPACITY</code>). Instead, the table is resized — a small table with a long chain usually means a poor hash function affecting all buckets, so spreading entries is the better fix.</p><p><strong>Q. What happens during a resize?</strong> A. A new table double the size is allocated; all entries are rehashed (O(n)). In Java 8, an entry either stays at the same index or moves to <code>oldIndex + oldCapacity</code>, determined by one bit of the cached hash.</p><p><strong>Q. Why is the default load factor 0.75?</strong> A. Empirical sweet spot: lower means too many empty buckets (wasted space), higher means more collisions (slower lookups).</p><p><strong>Q. Is HashMap thread-safe?</strong> A. No. Concurrent writes cause lost updates and potential corruption. Java 7 could produce an infinite loop during resize. Use <code>ConcurrentHashMap</code> for shared access.</p><p><strong>Q. Where does a null key land?</strong> A. Always at <code>table[0]</code> — <code>hash(null)</code> is defined as 0.</p><p><strong>Q. What happens if you mutate a key after inserting it into a HashMap?</strong> A. The map cached the hash at insert time. After mutation, <code>hashCode()</code> returns a different value, the map looks in the wrong bucket, and returns null. The entry is orphaned in the original bucket — silent data loss, no exception.</p>`,65)])])}const u=a(n,[["render",h]]);export{k as __pageData,u as default};
